"""Expected-label changes remain distinct from scenario edits before any costly check."""
from pathlib import Path
import sys,json,subprocess,re,copy
from interlock.case_template import case_template
root=Path(sys.argv[1]);left=case_template(['retry-conflict','retry-fixed']);right=copy.deepcopy(left);right['cases'][0]['expected_status']='branch_failure';right['cases'][0]['scenario']['name']='PRIVATE_CHANGED_SCENARIO';right['cases'].reverse();a=root/'left.json';b=root/'right.json';a.write_text(json.dumps(left));b.write_text(json.dumps(right));before=[a.read_bytes(),b.read_bytes()]
for name,other in [('same',a),('different',b)]:
 base=[sys.executable,'-m','interlock','compare-case-manifests',str(a),str(other)];r=subprocess.run(base,capture_output=True,text=True);assert r.returncode==0,r.stderr;report=json.loads(r.stdout);assert all(row['presence']=='both'for row in report['cases']);row=next(row for row in report['cases']if row['id']=='retry-conflict');assert row['expectation_changed']==row['scenario_changed']==(name=='different');assert row['right']['ordinal']==(1 if name=='same'else 2);h=subprocess.run(base+['--html'],capture_output=True,text=True);assert h.returncode==0 and 'PRIVATE_CHANGED_SCENARIO'not in h.stdout;assert json.loads(re.search(r'<script id="report-data" type="application/json">(.*?)</script>',h.stdout,re.S).group(1))==report;(root/(name+'.html')).write_text(h.stdout);(root/(name+'.json')).write_text(json.dumps(report))
assert [a.read_bytes(),b.read_bytes()]==before
code="from unittest.mock import patch;from interlock.cli import main\nwith patch('interlock.model_cases.check_many',side_effect=RuntimeError('search forbidden')):raise SystemExit(main(['compare-case-manifests',"+repr(str(a))+','+repr(str(b))+"]))";r=subprocess.run([sys.executable,'-c',code],capture_output=True);assert r.returncode==0
right['cases']=right['cases'][:1];right['cases'][0]['id']='new-case';b.write_text(json.dumps(right));r=subprocess.run([sys.executable,'-m','interlock','compare-case-manifests',str(a),str(b)],capture_output=True,text=True);assert r.returncode==0 and {row['presence']for row in json.loads(r.stdout)['cases']}=={'left_only','right_only'}
